import hashlib
import math

class BloomFilter:
    """
    A BloomFilter implementation that allows for space-efficient probabilistic data structure 
    capable of testing set membership, with the possibility of false positives.

    The optimal bit array size and number of hash functions are calculated based on the expected 
    number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._optimal_size()
        self.hash_count = self._optimal_hash_count()
        self.bit_array = [0] * self.size

    def _optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        return - (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)

    def _optimal_hash_count(self) -> int:
        """Calculate the optimal number of hash functions to use."""
        return (self.size / self.expected_items) * math.log(2)

    def _hashes(self, item: str) -> list:
        """Generate hash indices for the given item."""
        hash_indices = []
        for i in range(int(self.hash_count)):
            # Create a unique hash for each index using salt (i)
            hash_result = hashlib.md5((item + str(i)).encode()).hexdigest()
            hash_index = int(hash_result, 16) % self.size
            hash_indices.append(hash_index)
        return hash_indices

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True
